; hist.asm -- chapter 9: every sum of two bytes, counted by F
; generated by gen09.py
        INCLUDE "msx.inc"
        OUTPUT "hist.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
COUNTS  EQU $D000             ; in the RAM: 256 counters of two bytes for each operation
        ld hl, COUNTS
        ld de, COUNTS + 1
        ld (hl), 0
        ld bc, 2048 - 1
        ldir                    ; every counter to 0 (LDIR: chapter 13)
; add: counters at $D000 (low bytes) and $D100 (high bytes)
        ld d, 0                 ; D: the first number
add1:   ld e, 0                 ; E: the second
add2:   ld a, d
        add a, e                ; the operation counted
        push af
        pop bc                  ; C = F
        ld h, $D0               ; the page of low bytes
        ld l, c                 ; the counter for this value of F
        inc (hl)
        jr nz, add3
        inc h
        inc (hl)                ; the carry into its high byte
add3:   inc e
        jr nz, add2             ; all 256 values of E
        inc d
        jr nz, add1             ; for all 256 values of D
; adc: counters at $D200 (low bytes) and $D300 (high bytes)
        ld d, 0                 ; D: the first number
adc1:   ld e, 0                 ; E: the second
adc2:   ld a, d
        scf                     ; the carry in
        adc a, e                ; the operation counted
        push af
        pop bc                  ; C = F
        ld h, $D2               ; the page of low bytes
        ld l, c                 ; the counter for this value of F
        inc (hl)
        jr nz, adc3
        inc h
        inc (hl)                ; the carry into its high byte
adc3:   inc e
        jr nz, adc2             ; all 256 values of E
        inc d
        jr nz, adc1             ; for all 256 values of D
; sub: counters at $D400 (low bytes) and $D500 (high bytes)
        ld d, 0                 ; D: the first number
sub1:   ld e, 0                 ; E: the second
sub2:   ld a, d
        sub e                   ; the operation counted
        push af
        pop bc                  ; C = F
        ld h, $D4               ; the page of low bytes
        ld l, c                 ; the counter for this value of F
        inc (hl)
        jr nz, sub3
        inc h
        inc (hl)                ; the carry into its high byte
sub3:   inc e
        jr nz, sub2             ; all 256 values of E
        inc d
        jr nz, sub1             ; for all 256 values of D
; sbc: counters at $D600 (low bytes) and $D700 (high bytes)
        ld d, 0                 ; D: the first number
sbc1:   ld e, 0                 ; E: the second
sbc2:   ld a, d
        scf                     ; the carry in
        sbc a, e                ; the operation counted
        push af
        pop bc                  ; C = F
        ld h, $D6               ; the page of low bytes
        ld l, c                 ; the counter for this value of F
        inc (hl)
        jr nz, sbc3
        inc h
        inc (hl)                ; the carry into its high byte
sbc3:   inc e
        jr nz, sbc2             ; all 256 values of E
        inc d
        jr nz, sbc1             ; for all 256 values of D
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
